201	     * Adds a claim with an external reference (blank: none), refused when the reference is already used on the sheet,
202	     * and comma separated tags (blank: none).
203	     */
204	    @Transactional
205	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
206	            String corrects, String ref, String tagText) {
207	        RollupService.Snapshot before = rollup.snapshot(sheetId);
208	        Person person = people.findByIdAndSheetId(personId, sheetId)
209	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
210	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
211	        // Due by its person's terms on its date in business days after it, skipping the sheet's holidays now, fixed from now on;
212	        // its period is the one of its due-by.
213	        int terms = termsFor(sheetId, person, dated);
214	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, dated, terms);
215	        periods.requireOpen(sheetId, dueBy);
216	        person.requireClaimable(dated);
217	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
218	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
219	        claim.setCorrects(corrects);
220	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
221	        claim.setDueBy(dueBy);
222	        claim.setTerms(terms);
223	        // Taking the next list place locks the sheet, so two adds of the same reference do not both pass the check.
224	        claim.setListed(sheets.nextListed(sheetId));
225	        String reference = refOf(ref);
226	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)) {
227	            throw new ClaimRefException(reference);
228	        }
229	        claim.setRef(reference);
230	        claim.setTags(tagged(sheetId, tagText));
231	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
232	        Claim saved = claims.saveAndFlush(claim);
233	        log(sheetId, user, person, saved);
234	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved)
235	                + (saved.getRef() == null ? "" : " ref=" + saved.getRef())
236	                + (saved.getTags() == null ? "" : " tags=" + saved.getTags()));
237	        if (saved.isLateEntry()) {
238	            audit.recordOnCommit(record("LATE_ENTRY", user, person, saved));
239	        }
240	        rollup.recordChanges(sheetId, user, before);
241	        return saved;
