248	        Claim claim = claims.findForUpdate(id, sheetId)
249	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
250	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
251	        if (claim.getStatus() != ClaimStatus.DRAFT) {
252	            throw new ClaimNotEditableException(id, claim.getStatus());
253	        }
254	        // Not while another user has its editor open.
255	        if (claim.isLockedAgainst(user)) {
256	            throw new ClaimLockedException(id, claim.getLockedBy());
257	        }
