265	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
266	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
267	                .requireClaimable(dated);
268	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
269	        String reference = refOf(ref);
270	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, id)) {
271	            throw new ClaimRefException(reference);
272	        }
273	        claim.setRef(reference);
274	        claim.setTags(tagged(sheetId, tagText));
275	        claim.setAmount(amount);
276	        claim.setCorrects(corrects);
277	        claim.setDate(dated);
278	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
279	        claim.setNote(noteOf(note));
280	        claim.setEditedBy(user);
281	        // Saving the editor releases its lock.
282	        claim.setLockedBy(null);
283	        Claim saved = claims.saveAndFlush(claim);
