350	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status, String voidReason,
351	            LongSupplier batch) {
352	        Claim claim = claims.findForUpdate(id, sheetId)
353	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
354	        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
355	        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
356	            throw new ClaimStatusException(id, claim.getStatus(), status);
357	        }
358	        // The sheet's permission matrix decides which roles may open, settle or void.
359	        String action = switch (status) {
360	            case OPEN -> "open";
361	            case SETTLED -> "settle";
362	            case VOID -> "void";
363	            case DRAFT, PENDING, DELETED -> throw new ClaimStatusException(id, claim.getStatus(), status);
364	        };
365	        if (!roles.may(sheetId, user, action)) {
366	            throw new ClaimActionForbiddenException(id, user, action);
367	        }
368	        if (voidsSettled) {
369	            requireSettledVoidable(sheetId, user, claim);
370	        }
371	        periods.requireOpen(sheetId, claim.getDueBy());
372	        String reason = status == ClaimStatus.VOID ? requireVoidReason(sheetId, id, voidReason) : null;
373	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
374	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
375	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
376	        }
377	        // Four eyes: whoever opened or last edited a claim cannot also settle it.
378	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
379	            throw new ClaimSettledByOpenerException(id, user, "opened");
380	        }
381	        if (status == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
382	            throw new ClaimSettledByOpenerException(id, user, "last edited");
383	        }
384	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
385	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
386	        if (status == ClaimStatus.SETTLED) {
387	            requireProof(sheetId, person, claim);
388	        }
389	        if (status == ClaimStatus.OPEN) {
390	            requireNote(sheetId, person, claim);
391	            requireUnderCap(sheetId, claim);
392	        }
393	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
394	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
395	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
396	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
397	            BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
398	            if (limit != null && due != null && due.compareTo(limit) > 0) {
399	                status = ClaimStatus.PENDING;
400	            }
401	        }
402	        RollupService.Snapshot before = rollup.snapshot(sheetId);
403	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
404	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
405	        claim.setStatus(status);
406	        if (status == ClaimStatus.VOID) {
407	            claim.setVoidReason(reason);
408	        }
409	        // Settled one at a time, a claim carries no batch; settled by a bulk settle, it carries that batch's number.
410	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING) {
411	            claim.setSettleBatch(batch == null ? null : batch.getAsLong());
412	        }
413	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
414	        String number = claim.getNumber();
415	        if (status == ClaimStatus.OPEN) {
416	            number = nextNumber(sheetId, claim.getDueBy());
417	            claim.setNumber(number);
418	            claim.setOpenedBy(user);
419	        }
420	        Claim saved = claims.saveAndFlush(claim);
421	        log(sheetId, user, person, saved);
422	        String event = switch (status) {
423	            case OPEN -> "CLAIM_OPENED";
424	            case PENDING -> "CLAIM_PENDING";
425	            case SETTLED -> "CLAIM_SETTLED";
426	            case VOID -> "CLAIM_VOIDED";
427	            case DRAFT, DELETED -> throw new IllegalStateException();
428	        };
429	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
430	                + (reason == null ? "" : " reason=" + reason));
431	        if (status == ClaimStatus.SETTLED) {
432	            watches.notifyWatchers(sheetId, user, person, number);
433	        }
434	        rollup.recordChanges(sheetId, user, before);
435	        return saved;
436	    }
