440	     * restored. Refused for any other status, a claim due by a date in a closed period, or one another user's open
441	     * editor locks.
442	     */
443	    @Transactional
444	    public Claim delete(String sheetId, String user, Long id) {
445	        Claim claim = claims.findForUpdate(id, sheetId)
446	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
447	        if (claim.getStatus() != ClaimStatus.DRAFT) {
448	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.DELETED);
449	        }
450	        if (claim.isLockedAgainst(user)) {
