577	    /**
578	     * Reassign as {@link #reassign(String, String, Long, Long)}; with {@code toOwnAllowed} (a bulk reassign) a claim
579	     * already the person's is moved too, listed again as its newest claim.
580	     */
581	    @Transactional
582	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean toOwnAllowed) {
583	        Claim claim = claims.findForUpdate(id, sheetId)
584	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
585	        if (!roles.may(sheetId, user, "reassign")) {
586	            throw new ClaimReassignForbiddenException(id, user);
587	        }
588	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
589	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
590	        }
591	        if (!toOwnAllowed && claim.getPersonId().equals(toPersonId)) {
592	            throw new ClaimReassignException(id, "it is already that person's");
593	        }
594	        periods.requireOpen(sheetId, claim.getDueBy());
595	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
596	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
597	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
598	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
599	        to.requireClaimable(claim.getDate());
600	        RollupService.Snapshot before = rollup.snapshot(sheetId);
601	        claim.setPersonId(to.getId());
602	        claim.setStated(false, null);
603	        claim.setListed(sheets.nextListed(sheetId));
604	        if (claim.getNumber() != null) {
605	            // A moved claim takes the next number in its sequence; its old one is never used again.
606	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
607	        }
608	        Claim saved = claims.saveAndFlush(claim);
609	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
610	                + " from=" + from.getName() + " to=" + to.getName());
611	        rollup.recordChanges(sheetId, user, before);
612	        return saved;
