643	    /**
644	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
645	     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
646	     * status, a closed period, or a user not a steward.
647	     */
648	    @Transactional
649	    public Claim resettle(String sheetId, String user, Long id) {
650	        Claim claim = claims.findForUpdate(id, sheetId)
651	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
652	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
653	            throw new ClaimResettleForbiddenException(id, user);
654	        }
655	        if (claim.getStatus() != ClaimStatus.SETTLED) {
656	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
657	        }
658	        periods.requireOpen(sheetId, claim.getDueBy());
659	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
660	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
661	        RollupService.Snapshot before = rollup.snapshot(sheetId);
662	        String old = shownDue(sheetId, person, claim);
663	        BigDecimal figure = dueOf(sheetId, person, claim);
664	        Sheet sheet = settings.get(sheetId);
665	        claim.setSettledDue(claim.isCorrection() ? figure
666	                : sheet.floored(sheet.withLateCharge(figure, true, overdueBy(sheet, person, claim), claim.getDate()), claim.getDate()));
667	        Claim saved = claims.saveAndFlush(claim);
668	        log(sheetId, user, person, saved);
669	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
670	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
671	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
672	        rollup.recordChanges(sheetId, user, before);
673	        return saved;
674	    }
