710	    /**
711	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
712	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
713	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on that date,
714	     * names the claim's number as the one it was split from. Refused for any other status, a claim due by a date in a
715	     * closed period (the new claim's own due-by is not weighed), or a user
716	     * whose role may not open a claim.
717	     */
718	    @Transactional
719	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
720	        Claim claim = claims.findForUpdate(id, sheetId)
721	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
722	        if (!roles.may(sheetId, user, "open")) {
723	            throw new ClaimActionForbiddenException(id, user, "open");
724	        }
725	        if (claim.getStatus() != ClaimStatus.OPEN) {
726	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
727	        }
728	        if (claim.isDeferredOn(sheets.today(sheetId))) {
729	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
730	        }
731	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
732	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
733	                    + claim.getAmount().toPlainString());
734	        }
735	        periods.requireOpen(sheetId, claim.getDueBy());
736	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
737	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
738	        RollupService.Snapshot before = rollup.snapshot(sheetId);
739	        claim.setAmount(claim.getAmount().subtract(amount));
740	        claim.setStated(false, null);
741	        Claim kept = claims.saveAndFlush(claim);
742	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
743	        part.setRoundingDate(kept.getRoundingDate());
744	        part.setTerms(termsFor(sheetId, person, kept.getDate()));
745	        part.setDueBy(holidays.businessDaysAfter(sheetId, kept.getDate(), part.getTerms()));
746	        part.setListed(sheets.nextListed(sheetId));
747	        part.setLateEntry(periods.softClosedOn(sheetId, part.getDueBy()));
748	        part.setStatus(ClaimStatus.OPEN);
749	        String number = nextNumber(sheetId, part.getDueBy());
750	        part.setNumber(number);
751	        part.setOpenedBy(user);
752	        part.setSplitFrom(kept.getNumber());
753	        part.setTags(kept.getTags());
754	        Claim saved = claims.saveAndFlush(part);
755	        log(sheetId, user, person, saved);
756	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
757	                + " into=" + number);
758	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
759	        rollup.recordChanges(sheetId, user, before);
760	        return saved;
761	    }
