809	    /**
810	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date (its person's
811	     * grade's own then, else the sheet's) cannot be settled or approved while it has no proof; refused then. A due of
812	     * n/a is within any threshold.
813	     */
814	    private void requireProof(String sheetId, Person person, Claim claim) {
815	        BigDecimal threshold = settings.get(sheetId).proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
816	        if (threshold == null || claim.getProofs() > 0) {
817	            return;
818	        }
819	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
820	        if (due != null && due.compareTo(threshold) > 0) {
821	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
822	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
823	        }
824	    }
