826	    /**
827	     * A claim whose due is above the note threshold in force on its date cannot be opened while its note is empty;
828	     * refused then. A due of n/a is within any threshold.
829	     */
830	    /**
831	     * Refuse opening a claim when the period its due-by falls in caps each person's claims and its person already has
832	     * that many OPEN or PENDING claims due by a date in it. The sheet is locked by the caller, so two opens at once are
833	     * counted against each other.
834	     */
835	    private void requireUnderCap(String sheetId, Claim claim) {
836	        Period period = periods.on(sheetId, claim.getDueBy()).orElse(null);
837	        if (period == null || period.getCap() == null) {
838	            return;
839	        }
840	        long held = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, claim.getPersonId()).stream()
841	                .filter(c -> !c.getId().equals(claim.getId()))
842	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
843	                .filter(c -> c.getDueBy() != null && period.contains(c.getDueBy()))
844	                .count();
845	        if (held >= period.getCap()) {
846	            throw new ClaimCapException(claim.getId(), period.getName(), period.getCap());
847	        }
848	    }
