850	    private void requireNote(String sheetId, Person person, Claim claim) {
851	        BigDecimal threshold = settings.get(sheetId).noteThresholdOn(claim.getDate());
852	        if (threshold == null || !noteOf(claim.getNote()).isEmpty()) {
853	            return;
854	        }
855	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
856	        if (due != null && due.compareTo(threshold) > 0) {
857	            throw new ClaimNoteException(claim.getId(), "its due " + due.toPlainString()
858	                    + " is above the note threshold " + threshold.toPlainString() + " and its note is empty");
859	        }
