864	     * SETTLED line of its status log) by the sheet's today; refused otherwise.
865	     */
866	    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
867	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
868	            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
869	        }
870	        LocalDate settledOn = logOf(claim).stream()
871	                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
872	                .map(ClaimLog::getDate)
873	                .reduce((first, last) -> last)
874	                .orElse(null);
875	        LocalDate today = sheets.today(sheetId);
876	        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
877	            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
878	                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
879	        }
