882	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
883	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
884	        Claim claim = claims.findForUpdate(id, sheetId)
885	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
886	        if (claim.getStatus() != ClaimStatus.PENDING) {
887	            throw new ClaimStatusException(id, claim.getStatus(), to);
888	        }
889	        periods.requireOpen(sheetId, claim.getDueBy());
890	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
891	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
892	        }
