896	    /**
897	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
898	     * the rate on the claim's date) with its late charge, raised to the floor on its date, frozen in (a correction
899	     * freezes its bare figure); with no figure it stays live. Gives the due at the
900	     * end of its audit record.
901	     */
902	    private String settle(String sheetId, Person person, Claim claim) {
903	        BigDecimal figure = figureOf(sheetId, person, claim);
904	        Sheet sheet = settings.get(sheetId);
905	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
906	                : sheet.floored(figure.add(sheet.lateCharge(figure, overdueBy(sheet, person, claim), claim.getDate())), claim.getDate());
907	        claim.setSettledDue(settledDue);
908	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
909	    }
