911	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
912	    private void log(String sheetId, String user, Person person, Claim claim) {
913	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
914	                shownDue(sheetId, person, claim)));
915	    }
916	
917	    /**
918	     * The claim's due as shown: the one fixed when it was settled, else its live due; two decimals, or n/a.
919	     */
920	    private String shownDue(String sheetId, Person person, Claim claim) {
921	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
922	                : liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
923	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
924	    }
925	
926	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
927	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
928	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
929	    }
930	
931	    /**
932	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
933	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
934	     * for any other claim.
935	     */
936	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
937	        if (amount.signum() >= 0) {
938	            if (corrects != null) {
939	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
940	            }
941	            return null;
942	        }
943	        if (corrects == null) {
944	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
945	        }
946	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
947	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
948	                .map(Claim::getDate)
949	                .orElseThrow(() -> new ClaimCorrectionException(
950	                        "Claim " + corrects + " is not a settled claim of the same person"));
951	    }
952	
953	    /**
954	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
955	     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
956	     */
957	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
958	        Sheet sheet = settings.get(sheetId);
959	        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
960	                .map(Rate::getPct)
961	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
962	                .orElse(null);
963	    }
964	
965	    /**
966	     * The live due on a figure: the greater of the floor in force on the claim's date and the figure with the late
967	     * charge of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
968	     * on the sheet's today; a correction has neither floor nor late charge); null (n/a) stays null.
969	     */
970	    private BigDecimal liveDue(String sheetId, Person person, Claim claim, BigDecimal figure) {
971	        Sheet sheet = settings.get(sheetId);
972	        if (claim.isCorrection()) {
973	            return figure;
974	        }
975	        return sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen()
976	                && !claim.isDeferredOn(sheet.getToday()), overdueBy(sheet, person, claim), claim.getDate()), claim.getDate());
977	    }
978	
979	    /** The day the claim goes overdue after: its due-by plus the grace days its person's grade has on its date. */
980	    private static LocalDate overdueBy(Sheet sheet, Person person, Claim claim) {
981	        return sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
982	    }
983	
984	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
985	    private static String record(String event, String user, Person person, Claim claim) {
986	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
987	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
988	                + " date=" + claim.getDate();
989	    }
