1001	    public String nextNumber(String sheetId, LocalDate date) {
1002	        if (settings.get(sheetId).numbersByPeriod()) {
1003	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
1004	        }
1005	        return sheets.nextClaimNumber(sheetId, date);
