1024	    /**
1025	     * The tags of comma separated text, each trimmed and lower-cased, without repeats, sorted and joined by commas
1026	     * (null when there are none), each noted as used on the sheet.
1027	     */
1028	    private String tagged(String sheetId, String text) {
